import React, { useState, useEffect, forwardRef } from 'react';
import Select from 'react-select';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import './Filter.css';

// 只读且禁止输入/粘贴/拖拽的日期输入组件
const StrictReadOnlyInput = forwardRef((props, ref) => (
  <input
    {...props}
    ref={ref}
    readOnly
    className="date-picker"
    onKeyDown={e => e.preventDefault()}
    onPaste={e => e.preventDefault()}
    onDrop={e => e.preventDefault()}
  />
));

const Filter = ({ medications, adverseEvents, onFilterChange, onExportCSV, topSideEffectsPercent = 1, sideEffectBaseSize = 5, onTopSideEffectsPercentChange, onSideEffectBaseSizeChange, topSideEffectsCount = 0 }) => {
  const [medication, setMedication] = useState(null);
  const [adverseEvent, setAdverseEvent] = useState(null);
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);

  // Apply filters when any of the filter values change
  useEffect(() => {
    const formattedFilters = {
      medication: medication?.value || '',
      adverse_event: adverseEvent?.value || '',
      start_date: startDate ? formatDate(startDate) : '',
      end_date: endDate ? formatDate(endDate) : ''
    };

    onFilterChange(formattedFilters);
  }, [medication, adverseEvent, startDate, endDate]);

  // Format date as YYYY-MM-DD for API
  const formatDate = (date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const resetFilters = () => {
    setMedication(null);
    setAdverseEvent(null);
    setStartDate(null);
    setEndDate(null);
    // Reset sliders to default
    if (onTopSideEffectsPercentChange) onTopSideEffectsPercentChange(1);
    if (onSideEffectBaseSizeChange) onSideEffectBaseSizeChange(5);
    onFilterChange({
      medication: '',
      adverse_event: '',
      start_date: '',
      end_date: ''
    });
  };

  // Custom styles for react-select
  const selectStyles = {
    control: (styles) => ({
      ...styles,
      borderRadius: '4px',
      borderColor: '#ced4da',
      boxShadow: 'none',
      '&:hover': {
        borderColor: '#80bdff'
      }
    }),
    menu: (styles) => ({
      ...styles,
      zIndex: 999
    })
  };

  return (
    <div className="filter-container">
      <div className="filter-row">
        <div className="filter-group">
          <label htmlFor="medication">Medication</label>
          <Select
            id="medication"
            value={medication}
            onChange={setMedication}
            options={medications}
            placeholder="Select medication..."
            isClearable
            styles={selectStyles}
            className="filter-select"
          />
        </div>

        <div className="filter-group">
          <label htmlFor="adverse-event">Adverse Event</label>
          <Select
            id="adverse-event"
            value={adverseEvent}
            onChange={setAdverseEvent}
            options={adverseEvents}
            placeholder="Select adverse event..."
            isClearable
            isSearchable
            styles={selectStyles}
            className="filter-select"
          />
        </div>

        <div className="filter-group">
          <label htmlFor="start-date">Start Date</label>
          <DatePicker
            id="start-date"
            selected={startDate}
            onChange={date => setStartDate(date)}
            selectsStart
            startDate={startDate}
            endDate={endDate}
            maxDate={new Date()}
            placeholderText="Start date"
            className="date-picker"
            dateFormat="yyyy-MM-dd"
            isClearable
            shouldCloseOnSelect
            showMonthDropdown
            showYearDropdown
            customInput={<StrictReadOnlyInput />}
          />
        </div>

        <div className="filter-group">
          <label htmlFor="end-date">End Date</label>
          <DatePicker
            id="end-date"
            selected={endDate}
            onChange={date => setEndDate(date)}
            selectsEnd
            startDate={startDate}
            endDate={endDate}
            minDate={startDate}
            maxDate={new Date()}
            placeholderText="End date"
            className="date-picker"
            dateFormat="yyyy-MM-dd"
            isClearable
            shouldCloseOnSelect
            showMonthDropdown
            showYearDropdown
            customInput={<StrictReadOnlyInput />}
          />
        </div>

        {/* Top Side Effects Slider */}
        <div className="filter-group" style={{ minWidth: 220 }}>
          <label htmlFor="top-side-effects">Top Side Effects</label>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <input
              id="top-side-effects"
              type="range"
              min={1}
              max={100}
              value={topSideEffectsPercent}
              onChange={e => onTopSideEffectsPercentChange && onTopSideEffectsPercentChange(Number(e.target.value))}
              style={{ flex: 1 }}
            />
            <span style={{ minWidth: 70, fontSize: 13 }}>
              {topSideEffectsPercent}% ({topSideEffectsCount} effects)
            </span>
          </div>
        </div>

        {/* Side Effect Base Size Slider */}
        <div className="filter-group" style={{ minWidth: 180 }}>
          <label htmlFor="side-effect-base-size">Side Effect Base Size</label>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <input
              id="side-effect-base-size"
              type="range"
              min={1}
              max={10}
              value={sideEffectBaseSize}
              onChange={e => onSideEffectBaseSizeChange && onSideEffectBaseSizeChange(Number(e.target.value))}
              style={{ flex: 1 }}
            />
            <span style={{ minWidth: 20, fontSize: 13 }}>{sideEffectBaseSize}</span>
          </div>
        </div>

        <div className="filter-actions-vertical">
          <button className="btn btn-reset" onClick={resetFilters}>
            Reset Filters
          </button>
          <button className="btn btn-export" onClick={onExportCSV}>
            Export CSV
          </button>
        </div>
      </div>
    </div>
  );
};

export default Filter;
